"""UGEN kernel — generated by push_kernel.py; do not edit by hand."""
import os
import sys

# locate the pipeline dir and the frozen data regardless of how Kaggle unpacked the zips
# (Kaggle strips top-level zip folders), then reassemble an importable ugen package
import shutil

pipe_dir, data_dir = None, None
for dp, dns, fns in os.walk("/kaggle/input"):
    if "runner.py" in fns and "grading.py" in fns:
        pipe_dir = dp
    if "mmlu.jsonl" in fns and "MANIFEST.json" in fns:
        data_dir = dp
if pipe_dir is None or data_dir is None:
    listing = [os.path.join(dp, f) for dp, _, fns in os.walk("/kaggle/input")
               for f in fns][:80]
    raise SystemExit(f"layout not found: pipe={pipe_dir} data={data_dir}; saw {listing}")
pkg = "/kaggle/working/pkg"
shutil.rmtree(pkg, ignore_errors=True)
shutil.copytree(pipe_dir, os.path.join(pkg, "ugen", "pipeline"))
for init in (os.path.join(pkg, "ugen", "__init__.py"),
             os.path.join(pkg, "ugen", "pipeline", "__init__.py"),
             os.path.join(pkg, "ugen", "pipeline", "tests", "__init__.py")):
    os.makedirs(os.path.dirname(init), exist_ok=True)
    if not os.path.exists(init):
        open(init, "w").close()
sys.path.insert(0, pkg)
print(f"pipe={pipe_dir} data={data_dir}", flush=True)

import subprocess
import time

SPLIT = {0: ['musr', 'mmlu', 'bbh', 'commonsenseqa', 'mbpp', 'multiarith'], 1: ['mmlu_pro', 'truthfulqa', 'strategyqa', 'gsm8k', 'svamp', 'arc_challenge', 'humaneval', 'gpqa']}
procs = []
for gpu, benches in sorted(SPLIT.items()):
    wd = f"/kaggle/working/gpu{gpu}"
    os.makedirs(wd, exist_ok=True)
    env = dict(os.environ, CUDA_VISIBLE_DEVICES=str(gpu))
    code = (
        "import sys; sys.path.insert(0, '/kaggle/working/pkg')\n"
        "from ugen.pipeline.runner import main\n"
        f"main(model_hint='gemma-3-4b-it', model_name='Gemma-3-4B-IT', "
        f"benchmarks={benches!r}, data_dir={data_dir!r}, work_dir={wd!r}, "
        "seed=0, limit=None)\n")
    procs.append(subprocess.Popen([sys.executable, "-c", code], env=env))
    time.sleep(60)      # stagger model loads
rcs = [p.wait() for p in procs]
print(f"worker exit codes: {rcs}", flush=True)
if any(rcs):
    raise SystemExit(f"a GPU worker failed: {rcs}")
